using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Xunit;

public class RagQualityEvaluationTests
{
    private readonly IChatConfiguration _evalChatConfig;
    private readonly IEvaluator _groundednessEvaluator;
    private readonly IEvaluator _relevanceEvaluator;

    public RagQualityEvaluationTests()
    {
        // Configure judge model for evaluation
        var judgeClient = new OpenAIClient(Environment.GetEnvironmentVariable("OPENAI_API_KEY"))
            .AsChatClient("gpt-4o");

        _evalChatConfig = new ChatConfiguration(judgeClient);
        _groundednessEvaluator = new GroundednessEvaluator();
        _relevanceEvaluator = new RelevanceEvaluator();
    }

    [Theory]
    [InlineData("How do I enable auto-scaling on AKS?", "aks-docs-autoscaler.md")]
    [InlineData("What is the token limit for gpt-4o?", "openai-model-limits.md")]
    public async Task EvaluateGoldenDatasetAsync(string userQuestion, string expectedDocKey)
    {
        // 1. Run production RAG pipeline under test
        var ragService = TestFixture.GetProductionRagService();
        RagResponse response = await ragService.AskAsync(userQuestion);

        // 2. Assert Retrieval Quality (Recall check)
        Assert.Contains(response.RetrievedSources, s => s.DocumentKey == expectedDocKey);

        // 3. Evaluate Groundedness using Microsoft.Extensions.AI.Evaluation
        EvaluationResult groundednessResult = await _groundednessEvaluator.EvaluateAsync(
            messages: [new ChatMessage(ChatRole.User, userQuestion)],
            modelResponse: new ChatResponse(response.AnswerText),
            chatConfiguration: _evalChatConfig,
            additionalContext: [new EvaluationMetricContext("GroundingContext", string.Join("\n", response.RetrievedChunks))]);

        var score = groundednessResult.Get<NumericMetric>("Groundedness").Value;
        Assert.True(score >= 4.0, $"Groundedness score {score} fell below acceptable threshold for: {userQuestion}");

        // 4. Assert Latency budget
        Assert.True(response.LatencyMs < 2500, $"Response took {response.LatencyMs}ms, exceeding 2.5s budget.");
    }
}
